-- 📚 꼭집 주거 사전 — ㎡당 월임대료 — 유형별 위계 · 매입임대 시·도 차 · 2026
-- 재계산 SQL(관리 API에서 그대로 실행 · 읽기만). 범위: 공고일 2026년 · 유형은 housing_type_map 표준값 · 세대 행 기본 칸(monthly_rent > 0 ∧ area_sqm > 0).
-- 확인 2026-10-14 · 결과 요지: rows 6455 · anns 249 · 유형 중앙값 영구 2971 < 국민 3797 < 행복 4542 < 매입 5431 < 통합공공 6359 < 공공임대 8333 < 신혼희망 11019 < SH 고유 13121 · 매입 서울 14991 … 강원 2061
with a as(select distinct on(x.announcement_id)x.announcement_id,x.supply_org org,coalesce(m.std_type,x.housing_type)std,extract(year from coalesce(x.announcement_date,x.created_at::date))::int yr from announcements x left join housing_type_map m on m.source_table='announcements' and m.source=x.source and m.housing_type=x.housing_type order by x.announcement_id,(x.source='LH')desc,x.created_at desc),u as(select h.announcement_id,a.std,a.org,coalesce(nullif(btrim(h.sido_nm),''),'(시도 없음)')sido,h.monthly_rent::numeric/h.area_sqm v from housing_units h join a using(announcement_id) where a.yr=2026 and h.monthly_rent>0 and h.area_sqm>0),s as(select std,sido,count(*)n,count(distinct announcement_id)anns,round(percentile_cont(0.5)within group(order by v)::numeric)med,round(min(v))lo,round(max(v))hi from u group by 1,2)select json_build_object('rows',(select count(*) from u),'anns',(select count(distinct announcement_id) from u),'by_std',(select json_object_agg(std,j) from(select std,json_build_object('n',sum(n),'med',(select round(percentile_cont(0.5)within group(order by v)::numeric) from u u2 where u2.std=s.std))j from s group by std)q),'by_std_sido',(select json_agg(json_build_object('std',std,'sido',sido,'n',n,'anns',anns,'med',med,'lo',lo,'hi',hi) order by std,med desc) from s where anns>=2))j;
